abyss:
#TitleBar {
    background: transparent;
    border-bottom: 1px solid #0c1a22;
}
#TitleBarTitle { color: #4e6a72; background: transparent; }
#TitleBar QPushButton {
    background: transparent;
    color: #4e6a72;
    border: 0;
    border-radius: 6px;
    padding: 0;
}
#TitleBar QPushButton:hover { background: #0e1c26; color: #cfe8e4; }
#TitleBarClose:hover { background: #2ee6c8; color: #04090e; }
/* tide :: abyss (modern · deep-ocean) */

* {
    font-family: "Inter", "IBM Plex Sans", sans-serif;
    font-size: 10pt;
    color: #cfe8e4;
}

QMainWindow, QDialog, QWidget {
    background: #04090e;
    color: #cfe8e4;
}
QWidget:focus { outline: 0; }

QLabel { background: transparent; color: #cfe8e4; }
QLabel#dim, QLabel.dim { color: #4e6a72; }
QLabel#accent, QLabel.accent { color: #2ee6c8; }

/* ---------- inputs ---------- */
QLineEdit, QTextEdit, QPlainTextEdit, QSpinBox, QDoubleSpinBox {
    background: #0a141c;
    color: #cfe8e4;
    border: 1px solid #0c1a22;
    border-radius: 6px;
    padding: 8px 14px;
    selection-background-color: #2ee6c8;
    selection-color: #04090e;
}
QLineEdit:focus, QTextEdit:focus, QPlainTextEdit:focus,
QSpinBox:focus, QDoubleSpinBox:focus { border-color: #2ee6c8; }
QLineEdit:disabled, QTextEdit:disabled, QPlainTextEdit:disabled,
QSpinBox:disabled, QDoubleSpinBox:disabled { color: #4e6a72; }

QSpinBox::up-button, QDoubleSpinBox::up-button,
QSpinBox::down-button, QDoubleSpinBox::down-button {
    background: transparent;
    border: none;
    width: 16px;
}

/* ---------- buttons ---------- */
QPushButton, QToolButton {
    background: #0a141c;
    color: #cfe8e4;
    border: 1px solid #0c1a22;
    border-radius: 6px;
    padding: 6px 14px;
}
QPushButton:hover, QToolButton:hover { background: #0e1c26; color: #d8f2ee; border-color: #16323e; }
QPushButton:pressed, QToolButton:pressed { background: #2ee6c8; color: #04090e; }
QPushButton:disabled, QToolButton:disabled { color: #4e6a72; }
QPushButton:focus, QToolButton:focus { border-color: #2ee6c8; }
QToolButton::menu-indicator { image: none; }

QDialogButtonBox QPushButton { min-width: 90px; }

/* ---------- checkbox / radio ---------- */
QCheckBox, QRadioButton {
    background: transparent;
    color: #cfe8e4;
    spacing: 10px;
    padding: 2px 0;
}
QCheckBox::indicator {
    width: 16px;
    height: 16px;
    border: 1px solid #16323e;
    background: #0a141c;
    border-radius: 4px;
}
QRadioButton::indicator {
    width: 16px;
    height: 16px;
    border: 1px solid #16323e;
    background: #0a141c;
    border-radius: 8px;
}
QCheckBox::indicator:hover, QRadioButton::indicator:hover { border-color: #2ee6c8; }
QCheckBox::indicator:checked {
    background: #2ee6c8;
    border-color: #2ee6c8;
}
QRadioButton::indicator:checked {
    background: #2ee6c8;
    border-color: #2ee6c8;
}
QCheckBox::indicator:disabled, QRadioButton::indicator:disabled {
    border-color: #0c1a22;
    background: #0a141c;
}
QCheckBox:disabled, QRadioButton:disabled { color: #4e6a72; }

/* ---------- combo box ---------- */
QComboBox {
    background: #0a141c;
    color: #cfe8e4;
    border: 1px solid #0c1a22;
    border-radius: 6px;
    padding: 6px 10px;
}
QComboBox:hover { border-color: #16323e; }
QComboBox:focus { border-color: #2ee6c8; }
QComboBox::drop-down {
    subcontrol-origin: padding;
    subcontrol-position: top right;
    width: 22px;
    border-left: 0;
}
QComboBox::down-arrow { image: none; }
QComboBox QAbstractItemView {
    background: #0a141c;
    color: #cfe8e4;
    selection-background-color: #2ee6c8;
    selection-color: #04090e;
    border: 1px solid #16323e;
    border-radius: 6px;
    outline: 0;
    padding: 4px 0;
}
QComboBox QAbstractItemView::item { padding: 6px 12px; }

/* ---------- slider ---------- */
QSlider::groove:horizontal {
    height: 4px;
    background: #0c1a22;
    border-radius: 2px;
}
QSlider::handle:horizontal {
    background: #cfe8e4;
    border: 0;
    width: 14px;
    height: 14px;
    margin: -6px 0;
    border-radius: 7px;
}
QSlider::handle:horizontal:hover { background: #2ee6c8; }
QSlider::sub-page:horizontal { background: #2ee6c8; border-radius: 2px; }

/* ---------- group box ---------- */
QGroupBox {
    background: transparent;
    border: 1px solid #0c1a22;
    border-radius: 6px;
    margin-top: 14px;
    padding: 10px;
}
QGroupBox::title {
    subcontrol-origin: margin;
    subcontrol-position: top left;
    padding: 0 8px;
    color: #4e6a72;
}

/* ---------- tabs ---------- */
QTabWidget::pane {
    background: #04090e;
    border: 1px solid #0c1a22;
    border-radius: 6px;
}
QTabBar::tab {
    background: transparent;
    color: #4e6a72;
    border: 0;
    padding: 8px 16px;
    margin-right: 4px;
    border-radius: 6px;
}
QTabBar::tab:selected { color: #cfe8e4; background: #0a141c; }
QTabBar::tab:hover { color: #cfe8e4; }

/* ---------- list / tree views ---------- */
QListView, QListWidget, QTreeView {
    background: #04090e;
    color: #cfe8e4;
    border: 0;
    outline: 0;
    padding: 4px 0;
}
QListView::item, QListWidget::item, QTreeView::item {
    padding: 8px 14px;
    border-radius: 6px;
    margin: 2px 4px;
    border: 0;
}
QListView::item:hover, QListWidget::item:hover, QTreeView::item:hover {
    background: #0e1c26;
}
QListView::item:selected, QListWidget::item:selected, QTreeView::item:selected {
    background: #2ee6c8;
    color: #04090e;
}
QListView::item:focus { border: 0; }

QHeaderView::section {
    background: transparent;
    color: #4e6a72;
    border: 0;
    border-bottom: 1px solid #0c1a22;
    padding: 8px 12px;
}

/* ---------- scroll area + scrollbars ---------- */
QScrollArea {
    background: #04090e;
    border: 0;
}
QAbstractScrollArea > QWidget > QWidget { background: #04090e; }

QScrollBar:vertical, QScrollBar:horizontal {
    background: transparent;
    width: 10px;
    height: 10px;
    margin: 0;
    border: 0;
}
QScrollBar::handle:vertical, QScrollBar::handle:horizontal {
    background: #16323e;
    border-radius: 5px;
    min-height: 30px;
    min-width: 30px;
}
QScrollBar::handle:hover { background: #4e6a72; }
QScrollBar::add-line, QScrollBar::sub-line { width: 0; height: 0; background: transparent; }
QScrollBar::add-page, QScrollBar::sub-page { background: transparent; }

/* ---------- status bar ---------- */
QStatusBar { background: #04090e; color: #4e6a72; border: 0; }
QStatusBar::item { border: 0; }

/* ---------- tooltips ---------- */
QToolTip {
    background: #0a141c;
    color: #cfe8e4;
    border: 1px solid #16323e;
    padding: 6px 10px;
    border-radius: 6px;
}

/* ---------- right-click menus ---------- */
QMenu {
    background: #0a141c;
    color: #cfe8e4;
    border: 1px solid #16323e;
    border-radius: 6px;
    padding: 6px 0;
}
QMenu::item { padding: 7px 22px; background: transparent; border-radius: 0; }
QMenu::item:selected { background: #2ee6c8; color: #04090e; }
QMenu::separator { height: 1px; background: #0c1a22; margin: 4px 8px; }
QMenu::icon { padding-left: 8px; }

/* ---------- now-playing strip + nav rail ---------- */
QFrame#now_playing {
    background: #0a141c;
    border-top: 1px solid #16323e;
}
QFrame#nav {
    background: #0a141c;
    border-right: 0;   /* modern themes: no nav divider */
}

QWidget#appShell,
QWidget#appSurface,
QWidget#appUpper,
QFrame#nav,
QFrame#now_playing,
QStackedWidget#contentStack,
QStackedWidget#contentStack > QWidget,
QStackedWidget#contentStack QStackedWidget,
QStackedWidget#contentStack QScrollArea,
QStackedWidget#contentStack QScrollArea > QWidget,
QStackedWidget#contentStack QScrollArea > QWidget > QWidget,
QStackedWidget#contentStack QListView,
QStackedWidget#contentStack QListWidget,
QStackedWidget#contentStack QTreeView,
QStackedWidget#contentStack QListView > QWidget,
QStackedWidget#contentStack QListWidget > QWidget,
QStackedWidget#contentStack QTreeView > QWidget,
QStackedWidget#contentStack #lyricsKaraoke,
QStackedWidget#contentStack .QWidget {
    background: transparent;
}
