undertow:
#TitleBar {
    background: transparent;
    border-bottom: 1px solid #181c30;
}
#TitleBarTitle { color: #565b7a; background: transparent; }
#TitleBar QPushButton {
    background: transparent;
    color: #565b7a;
    border: 0;
    border-radius: 2px;
    padding: 0;
}
#TitleBar QPushButton:hover { background: #1e2238; color: #d6d9ea; }
#TitleBarClose:hover { background: #c22940; color: #10121f; }
/* tide :: undertow (modern · indigo depths) */

* {
    font-family: "Inter", "IBM Plex Sans", sans-serif;
    font-size: 10pt;
    color: #d6d9ea;
}

QMainWindow, QDialog, QWidget {
    background: #10121f;
    color: #d6d9ea;
}
QWidget:focus { outline: 0; }

QLabel { background: transparent; color: #d6d9ea; }
QLabel#dim, QLabel.dim { color: #565b7a; }
QLabel#accent, QLabel.accent { color: #c22940; }

/* ---------- inputs ---------- */
QLineEdit, QTextEdit, QPlainTextEdit, QSpinBox, QDoubleSpinBox {
    background: #181b2e;
    color: #d6d9ea;
    border: 1px solid #181c30;
    border-radius: 2px;
    padding: 8px 14px;
    selection-background-color: #c22940;
    selection-color: #10121f;
}
QLineEdit:focus, QTextEdit:focus, QPlainTextEdit:focus,
QSpinBox:focus, QDoubleSpinBox:focus { border-color: #c22940; }
QLineEdit:disabled, QTextEdit:disabled, QPlainTextEdit:disabled,
QSpinBox:disabled, QDoubleSpinBox:disabled { color: #565b7a; }

QSpinBox::up-button, QDoubleSpinBox::up-button,
QSpinBox::down-button, QDoubleSpinBox::down-button {
    background: transparent;
    border: none;
    width: 16px;
}

/* ---------- buttons ---------- */
QPushButton, QToolButton {
    background: #181b2e;
    color: #d6d9ea;
    border: 1px solid #181c30;
    border-radius: 2px;
    padding: 6px 14px;
}
QPushButton:hover, QToolButton:hover { background: #1e2238; color: #e6e9f6; border-color: #262b48; }
QPushButton:pressed, QToolButton:pressed { background: #c22940; color: #f5e6e9; }
QPushButton:disabled, QToolButton:disabled { color: #565b7a; }
QPushButton:focus, QToolButton:focus { border-color: #c22940; }
QToolButton::menu-indicator { image: none; }

QDialogButtonBox QPushButton { min-width: 90px; }

/* ---------- checkbox / radio ---------- */
QCheckBox, QRadioButton {
    background: transparent;
    color: #d6d9ea;
    spacing: 10px;
    padding: 2px 0;
}
QCheckBox::indicator {
    width: 16px;
    height: 16px;
    border: 1px solid #262b48;
    background: #181b2e;
    border-radius: 4px;
}
QRadioButton::indicator {
    width: 16px;
    height: 16px;
    border: 1px solid #262b48;
    background: #181b2e;
    border-radius: 8px;
}
QCheckBox::indicator:hover, QRadioButton::indicator:hover { border-color: #c22940; }
QCheckBox::indicator:checked {
    background: #c22940;
    border-color: #c22940;
}
QRadioButton::indicator:checked {
    background: #c22940;
    border-color: #c22940;
}
QCheckBox::indicator:disabled, QRadioButton::indicator:disabled {
    border-color: #181c30;
    background: #181b2e;
}
QCheckBox:disabled, QRadioButton:disabled { color: #565b7a; }

/* ---------- combo box ---------- */
QComboBox {
    background: #181b2e;
    color: #d6d9ea;
    border: 1px solid #181c30;
    border-radius: 2px;
    padding: 6px 10px;
}
QComboBox:hover { border-color: #262b48; }
QComboBox:focus { border-color: #c22940; }
QComboBox::drop-down {
    subcontrol-origin: padding;
    subcontrol-position: top right;
    width: 22px;
    border-left: 0;
}
QComboBox::down-arrow { image: none; }
QComboBox QAbstractItemView {
    background: #181b2e;
    color: #d6d9ea;
    selection-background-color: #c22940;
    selection-color: #f5e6e9;
    border: 1px solid #262b48;
    border-radius: 2px;
    outline: 0;
    padding: 4px 0;
}
QComboBox QAbstractItemView::item { padding: 6px 12px; }

/* ---------- slider ---------- */
QSlider::groove:horizontal {
    height: 4px;
    background: #181c30;
    border-radius: 2px;
}
QSlider::handle:horizontal {
    background: #d6d9ea;
    border: 0;
    width: 14px;
    height: 14px;
    margin: -6px 0;
    border-radius: 7px;
}
QSlider::handle:horizontal:hover { background: #c22940; }
QSlider::sub-page:horizontal { background: #c22940; border-radius: 2px; }

/* ---------- group box ---------- */
QGroupBox {
    background: transparent;
    border: 1px solid #181c30;
    border-radius: 2px;
    margin-top: 14px;
    padding: 10px;
}
QGroupBox::title {
    subcontrol-origin: margin;
    subcontrol-position: top left;
    padding: 0 8px;
    color: #565b7a;
}

/* ---------- tabs ---------- */
QTabWidget::pane {
    background: #10121f;
    border: 1px solid #181c30;
    border-radius: 2px;
}
QTabBar::tab {
    background: transparent;
    color: #565b7a;
    border: 0;
    padding: 8px 16px;
    margin-right: 4px;
    border-radius: 2px;
}
QTabBar::tab:selected { color: #d6d9ea; background: #181b2e; }
QTabBar::tab:hover { color: #d6d9ea; }

/* ---------- list / tree views ---------- */
QListView, QListWidget, QTreeView {
    background: #10121f;
    color: #d6d9ea;
    border: 0;
    outline: 0;
    padding: 4px 0;
}
QListView::item, QListWidget::item, QTreeView::item {
    padding: 8px 14px;
    border-radius: 6px;
    margin: 2px 4px;
    border: 0;
}
QListView::item:hover, QListWidget::item:hover, QTreeView::item:hover {
    background: #1e2238;
}
QListView::item:selected, QListWidget::item:selected, QTreeView::item:selected {
    background: #c22940;
    color: #f5e6e9;
}
QListView::item:focus { border: 0; }

QHeaderView::section {
    background: transparent;
    color: #565b7a;
    border: 0;
    border-bottom: 1px solid #181c30;
    padding: 8px 12px;
}

/* ---------- scroll area + scrollbars ---------- */
QScrollArea {
    background: #10121f;
    border: 0;
}
QAbstractScrollArea > QWidget > QWidget { background: #10121f; }

QScrollBar:vertical, QScrollBar:horizontal {
    background: transparent;
    width: 10px;
    height: 10px;
    margin: 0;
    border: 0;
}
QScrollBar::handle:vertical, QScrollBar::handle:horizontal {
    background: #262b48;
    border-radius: 5px;
    min-height: 30px;
    min-width: 30px;
}
QScrollBar::handle:hover { background: #565b7a; }
QScrollBar::add-line, QScrollBar::sub-line { width: 0; height: 0; background: transparent; }
QScrollBar::add-page, QScrollBar::sub-page { background: transparent; }

/* ---------- status bar ---------- */
QStatusBar { background: #10121f; color: #565b7a; border: 0; }
QStatusBar::item { border: 0; }

